    // 8-bit ALU with arithmetic, logical, and comparison operations
module alu_8bit (
    input wire clk,
    input wire rst,
    input wire [7:0] a,
    input wire [7:0] b,
    input wire [3:0] opcode,
    output reg [7:0] result,
    output reg zero,
    output reg overflow,
    output reg negative
);

    // Internal signals for combinational logic
    reg [7:0] temp_result;
    reg temp_overflow;

    // Combinational logic for ALU operations
    always @(*) begin
        temp_overflow = 1'b0;
        temp_result = 8'b0;
        
        case (opcode)
            4'b0000: begin // ADD: A + B
                temp_result = a + b;
                // Overflow occurs when operands have same sign and result has different sign
                temp_overflow = (a[7] & b[7] & ~temp_result[7]) |
                                (~a[7] & ~b[7] & temp_result[7]);
            end
            
            4'b0001: begin // SUB: A - B
                temp_result = a - b;
                // Overflow occurs when A is positive, B is negative, and result is negative
                // or A is negative, B is positive, and result is positive
                temp_overflow = (a[7] & ~b[7] & ~temp_result[7]) |
                                (~a[7] & b[7] & temp_result[7]);
            end
            
            4'b0010: temp_result = a & b;  // AND
            
            4'b0011: temp_result = a | b;  // OR
            
            4'b0100: temp_result = a ^ b;  // XOR
            
            4'b0101: begin // SLL: Logical left shift
                // Shift amount is lower 3 bits of B (since 8-bit = 2^3)
                integer i;
                temp_result = 8'b0;
                for (i = 0; i < 8; i = i + 1) begin
                    if (i + b[2:0] < 8)
                        temp_result[i + b[2:0]] = a[i];
                end
            end
            
            4'b0110: begin // SRL: Logical right shift (zero-filled)
                integer i;
                temp_result = 8'b0;
                for (i = 0; i < 8; i = i + 1) begin
                    if (i >= b[2:0])
                        temp_result[i - b[2:0]] = a[i];
                end
            end
            
            4'b0111: begin // SRA: Arithmetic right shift (sign-extended)
                integer i;
                temp_result = 8'b0;
                for (i = 0; i < 8; i = i + 1) begin
                    if (i >= b[2:0])
                        temp_result[i - b[2:0]] = a[i];
                    else
                        temp_result[i - b[2:0]] = a[7]; // sign extension
                end
            end
            
            4'b1000: begin // SLT: Signed set less than (two's complement)
                if (a < b) // signed comparison
                    temp_result = 8'b1;
                else
                    temp_result = 8'b0;
            end
            
            4'b1001: begin // SLTU: Unsigned set less than
                if (a < b) // unsigned comparison
                    temp_result = 8'b1;
                else
                    temp_result = 8'b0;
            end
            
            default: temp_result = 8'b0;
        endcase
    end

    // Sequential logic for output registers
    always @(posedge clk) begin
        if (rst) begin
            result <= 8'b0;
            zero <= 1'b0;
            overflow <= 1'b0;
            negative <= 1'b0;
        end else begin
            result <= temp_result;
            zero <= (temp_result == 8'b0);
            overflow <= temp_overflow;
            negative <= temp_result[7];
        end
    end

endmodule